9	// retryDelay returns how long to wait before re-sending an alert.
10	func retryDelay(a models.Alert) time.Duration {
11		if a.Channel == "pagerduty" {
12			return 500 * time.Millisecond
13		}
14		if a.Channel == "slack" {
15			return 2 * time.Second
