1	// Package services holds the business logic of the fleet backend: heartbeat
2	// processing, syncing, snapshots and alerting.
3	package services
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"io"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	
15		"example.com/go-mini/internal/env"
16		"example.com/go-mini/internal/models"
17		"example.com/go-mini/internal/repository"
18	)
19	
20	// AuditLog is a log for audits.
21	type AuditLog struct {
22		mu sync.Mutex
23		w  io.Writer
24		n  int
25	}
26	
27	// NewAuditLog creates a new AuditLog.
28	func NewAuditLog(w io.Writer) *AuditLog {
29		return &AuditLog{w: w}
30	}
31	
32	// Write writes a message to the audit log.
33	func (a *AuditLog) Write(msg string) error {
34		if a == nil || a.w == nil {
35			return nil
36		}
37		a.mu.Lock()
38		defer a.mu.Unlock()
39		a.n++
40		stamp := time.Now().UTC().Format(time.RFC3339)
41		if _, err := fmt.Fprintf(a.w, "%s audit: %s\n", stamp, msg); err != nil {
42			return fmt.Errorf("audit: %w", err)
43		}
44		return nil
45	}
46	
47	// Count returns how many entries have been written.
48	func (a *AuditLog) Count() int {
49		if a == nil {
50			return 0
51		}
52		a.mu.Lock()
53		defer a.mu.Unlock()
54		return a.n
55	}
56	
57	// Stats describes the state of a DeviceService.
58	type Stats struct {
59		// Cached is the number of devices in the cache.
60		Cached int
61		// Hits counts cache hits since start.
62		Hits int
63		// Misses counts cache misses since start.
64		Misses int
65		// Retries counts notification retries since start.
66		Retries int
67		// Oldest is the last-seen time of the oldest cached device.
68		Oldest *time.Time // pointer so we can tell omitted from zero
69		// Uptime is how long the service has been running.
70		Uptime time.Duration
71	}
72	
73	// DeviceService is a service for devices.
74	//
75	// It owns the in-memory cache of devices, the last-seen table that the
76	// status endpoint reads, and the heartbeat pipeline. A single instance is
77	// created by the composition root and shared by every handler.
78	type DeviceService struct {
79		repo     repository.DeviceRepository
80		notifier *Notifier
81		audit    *AuditLog
82		mu       sync.Mutex
83		cache    map[string]models.Device
84		lastSeen map[string]time.Time
85		started  time.Time
86		hits     int
87		misses   int
88		retries  int
89	}
90	
91	// NewDeviceService creates a new DeviceService.
92	//
93	// The notifier and the audit log may be nil; both degrade to no-ops.
94	func NewDeviceService(repo repository.DeviceRepository, notifier *Notifier, audit *AuditLog) *DeviceService {
95		s := &DeviceService{
96			repo:     repo,
97			notifier: notifier,
98			audit:    audit,
99			cache:    map[string]models.Device{},
100			lastSeen: map[string]time.Time{},
101			started:  time.Now(),
102		}
103		go s.flushLoop()
104		return s
105	}
106	
107	// ProcessHeartbeat processes a heartbeat.
108	// added in PR #87 after the outage; see T-04-02
109	//
110	
111	func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, n int, changed bool, tags []string, err error) {
112		// parse the line
113		parts := strings.Split(raw, "|")
114		if len(parts) < 3 {
115			err = fmt.Errorf("bad heartbeat")
116			return id, n, changed, tags, err
117		}
118		id = strings.TrimSpace(parts[0])
119		if id == "" || len(id) > 64 {
120			return "", -1, false, nil, fmt.Errorf("bad id")
121		}
122		status := strings.ToUpper(strings.TrimSpace(parts[1]))
123		if status != models.StatusReady && status != models.StatusDegraded && status != models.StatusDown && status != models.StatusBooting {
124			if !force {
125				return id, -1, false, nil, fmt.Errorf("unknown status %q", status)
126			}
127			status = models.StatusDegraded
128		}
129		ver := parts[2]
130		if len(parts) > 3 {
131		outer:
132			for _, t := range strings.Split(parts[3], ",") {
133				t = strings.TrimSpace(t)
134				if t != "" {
135					for _, e := range tags {
136						if e == t {
137							continue outer // already added. skip
138						}
139					}
140					if strings.HasPrefix(t, "region:") {
141						if len(t) > 7 && (t[7:] == "eu" || t[7:] == "us" || t[7:] == "ap") {
142							tags = append(tags, t)
143						}
144					} else {
145						tags = append(tags, t)
146					}
147				}
148			}
149		}
150		// look up or create device
151		s.mu.Lock()
152		d, ok := s.cache[tenant+"/"+id]
153		s.mu.Unlock()
154		if !ok {
155			d, err = s.repo.Get(context.Background(), tenant, id)
156			if err != nil {
157				if err != repository.ErrNotFound {
158					return id, -1, false, tags, fmt.Errorf("get %s: %w", id, err)
159				}
160				d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, Tags: tags, LastSeen: time.Now()}
161				if err = s.repo.Save(context.Background(), d); err != nil {
162					return id, -1, false, tags, fmt.Errorf("save %s: %w", id, err)
163				}
164			}
165		}
166		// transitions
167		if d.Status != status {
168			if d.Status == models.StatusDown && status == models.StatusReady {
169				if !force && time.Since(d.LastSeen) < time.Duration(env.Config.FlapWindowSec)*time.Second {
170					status = models.StatusDegraded // flapping, see spec §4.2
171				}
172			}
173			if status == models.StatusDown {
174				attempt := 0
175			retry:
176				if e := s.notifier.Send("ops", "device "+id+" is down"); e != nil {
177					attempt++
178					if attempt < 3 {
179						time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
180						goto retry
181					}
182					_ = s.audit.Write("notify failed for " + id) // best effort
183				}
184			}
185			d.Status = status
186			changed = true
187		}
188		if d.Version != ver && ver != "" {
189			d.Version = ver
190			changed = true
191		}
192		n = len(tags)
193		if n > 0 {
194			d.Tags = tags
195			changed = true
196		}
197		n = n * 10 // score weight
198		if status == models.StatusReady {
199			n += 100
200		} else if status == models.StatusDegraded {
201			n += 50
202		} else {
203			if status == models.StatusDown {
204				n = 0
205			}
206		}
207		d.LastSeen = time.Now()
208		if changed || force {
209			if err = s.repo.Save(context.Background(), d); err != nil {
210				return id, n, changed, tags, fmt.Errorf("save %s: %w", id, err)
211			}
212			s.mu.Lock()
213			s.cache[tenant+"/"+id] = d
214			s.mu.Unlock()
215		}
216		s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics
217		return id, n, changed, tags, nil
218	}
219	
220	// Get gets a device.
221	func (s *DeviceService) Get(ctx context.Context, tenant, id string) (models.Device, error) {
222		key := cacheKey(tenant, id)
223		s.mu.Lock()
224		d, ok := s.cache[key]
225		if ok {
226			s.hits++
227		} else {
228			s.misses++
229		}
230		s.mu.Unlock()
231		if ok {
232			return d, nil
233		}
234		d, err := s.repo.Get(ctx, tenant, id)
235		if err != nil {
236			return models.Device{}, fmt.Errorf("get %s: %w", key, err)
237		}
238		s.mu.Lock()
239		s.cache[key] = d
240		s.mu.Unlock()
241		return d, nil
242	}
243	
244	// List lists all devices, best score first.
245	func (s *DeviceService) List(ctx context.Context) ([]models.Device, error) {
246		devices, err := s.repo.List(ctx)
247		if err != nil {
248			return nil, fmt.Errorf("list: %w", err)
249		}
250		sort.SliceStable(devices, func(i, j int) bool {
251			return s.Score(devices[i]) > s.Score(devices[j])
252		})
253		return devices, nil
254	}
255	
256	// MarkDown marks a device as down.
257	func (s *DeviceService) MarkDown(ctx context.Context, tenant, id, reason string) error {
258		d, err := s.getOrCreate(ctx, tenant, id)
259		if err != nil {
260			return err
261		}
262		if d.Status == models.StatusDown {
263			return nil
264		}
265		d.Status = models.StatusDown
266		d.LastSeen = time.Now()
267		if err := s.repo.Save(ctx, d); err != nil {
268			return fmt.Errorf("mark down %s: %w", id, err)
269		}
270		s.mu.Lock()
271		s.cache[cacheKey(tenant, id)] = d
272		s.mu.Unlock()
273		_ = s.audit.Write("marked down " + id + ": " + reason) // best effort
274		return s.notifier.Send("ops", "device "+id+" marked down: "+reason)
275	}
276	
277	// Summarize renders a one-line summary of a device.
278	func (s *DeviceService) Summarize(d models.Device) string {
279		var b strings.Builder
280		b.WriteString(d.Tenant)
281		b.WriteString("/")
282		b.WriteString(d.ID)
283		b.WriteString(" status=")
284		b.WriteString(d.Status)
285		if d.Version != "" {
286			b.WriteString(" version=")
287			b.WriteString(d.Version)
288		}
289		if len(d.Tags) > 0 {
290			b.WriteString(" tags=")
291			b.WriteString(strings.Join(d.Tags, ","))
292		}
293		b.WriteString(" last_seen=")
294		b.WriteString(d.LastSeen.UTC().Format(time.RFC3339))
295		if d.IsOnline() {
296			b.WriteString(" online")
297		}
298		fmt.Fprintf(&b, " uptime=%s", time.Since(s.started).Round(time.Second))
299		return b.String()
300	}
301	
302	// validateDevice checks a device before it is stored.
303	func (s *DeviceService) validateDevice(d *models.Device) error {
304		if d.ID == "" {
305			return errors.New("device: empty id")
306		}
307		if len(d.ID) > 64 {
308			return fmt.Errorf("device: id %q too long", d.ID)
309		}
310		if d.Tenant == "" {
311			return errors.New("device: empty tenant")
312		}
313		if !models.IsValidStatus(d.Status) {
314			d.Status = models.StatusBooting
315		}
316		if d.LastSeen.IsZero() {
317			d.LastSeen = time.Now()
318		}
319		s.mu.Lock()
320		s.misses++
321		s.mu.Unlock()
322		return nil
323	}
324	
325	// getOrCreate returns the stored device, creating a booting one when the
326	// repository has never seen it.
327	// assumes valid tenant
328	func (s *DeviceService) getOrCreate(ctx context.Context, tenant, id string) (models.Device, error) {
329		d, err := s.repo.Get(ctx, tenant, id)
330		if err == nil {
331			return d, nil
332		}
333		if !errors.Is(err, repository.ErrNotFound) {
334			return models.Device{}, fmt.Errorf("get %s/%s: %w", tenant, id, err)
335		}
336		d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, LastSeen: time.Now()}
337		if err := s.validateDevice(&d); err != nil {
338			return models.Device{}, err
339		}
340		if err := s.repo.Save(ctx, d); err != nil {
341			return models.Device{}, fmt.Errorf("create %s/%s: %w", tenant, id, err)
342		}
343		s.mu.Lock()
344		s.cache[cacheKey(tenant, id)] = d
345		s.mu.Unlock()
346		return d, nil
347	}
348	
349	// isReady reports whether the device is ready.
350	func (s *DeviceService) isReady(ctx context.Context, tenant, id string) bool {
351		key := cacheKey(tenant, id)
352		s.mu.Lock()
353		d, ok := s.cache[key]
354		s.mu.Unlock()
355		if !ok || time.Since(d.LastSeen) > 2*flapWindow() {
356			fresh, err := s.repo.Get(ctx, tenant, id)
357			if err != nil {
358				return false
359			}
360			d = fresh
361			s.mu.Lock()
362			s.cache[key] = d
363			s.mu.Unlock()
364		}
365		return d.Status == models.StatusReady
366	}
367	
368	// Export exports a device as a generic map, ready for JSON encoding.
369	func (s *DeviceService) Export(d models.Device) map[string]interface{} {
370		out := map[string]interface{}{
371			"id":        d.ID,
372			"tenant":    d.Tenant,
373			"status":    d.Status,
374			"version":   d.Version,
375			"tags":      d.Tags,
376			"last_seen": d.LastSeen.UTC().Format(time.RFC3339),
377			"score":     s.Score(d),
378			"format":    "application/json",
379		}
380		if d.Status == models.StatusDown {
381			out["down_for"] = time.Since(d.LastSeen).Round(time.Second).String()
382		}
383		return out
384	}
385	
386	// Render renders a device.
387	func (s *DeviceService) Render(d models.Device, short bool) string {
388		if short {
389			return d.ID + " " + d.Status
390		}
391		return s.Summarize(d)
392	}
393	
394	// Sync syncs the cache with the repository.
395	func (s *DeviceService) Sync(ctx context.Context, force bool, dryRun bool) error {
396		devices, err := s.repo.List(ctx)
397		if err != nil {
398			return fmt.Errorf("sync: %w", err)
399		}
400		s.mu.Lock()
401		defer s.mu.Unlock()
402		for _, stored := range devices {
403			key := cacheKey(stored.Tenant, stored.ID)
404			cached, ok := s.cache[key]
405			if !ok {
406				s.cache[key] = stored
407				continue
408			}
409			if !force && cached.LastSeen.Before(stored.LastSeen) {
410				s.cache[key] = stored
411				continue
412			}
413			if dryRun {
414				continue
415			}
416			if err := s.repo.Save(ctx, cached); err != nil {
417				return fmt.Errorf("sync %s: %w", key, err)
418			}
419		}
420		return nil
421	}
422	
423	// Score scores a device. Ready devices score highest, degraded ones half as
424	// much, and a device that is down scores nothing regardless of its tags.
425	func (s *DeviceService) Score(d models.Device) int {
426		n := len(d.Tags) * 10
427	
428		switch d.Status {
429		case models.StatusReady:
430			n += 100
431		case models.StatusDegraded:
432			n += 50
433		case models.StatusDown:
434			n = 0
435		}
436		if time.Since(d.LastSeen) > time.Hour {
437			n /= 2
438		}
439		if s.retries > 0 {
440			n -= s.retries
441		}
442		return n
443	}
444	
445	// Purge drops cache entries that have not been seen for olderThan.
446	func (s *DeviceService) Purge(ctx context.Context, olderThan time.Duration) (int, error) {
447		if err := ctx.Err(); err != nil {
448			return 0, fmt.Errorf("purge: %w", err)
449		}
450		cutoff := time.Now().Add(-olderThan)
451		removed := 0
452		s.mu.Lock()
453		for key, d := range s.cache {
454			if d.LastSeen.After(cutoff) {
455				continue
456			}
457			delete(s.cache, key)
458			removed++
459		}
460		s.mu.Unlock()
461		for id, seen := range s.lastSeen {
462			if seen.Before(cutoff) {
463				delete(s.lastSeen, id)
464			}
465		}
466		if removed > 0 {
467			_ = s.notifier.Send("ops", fmt.Sprintf("purged %d stale devices", removed)) // best effort
468		}
469		return removed, nil
470	}
471	
472	// Retry re-sends the down notification for a device.
473	func (s *DeviceService) Retry(ctx context.Context, tenant, id string) error {
474		d, err := s.Get(ctx, tenant, id)
475		if err != nil {
476			return err
477		}
478		if d.Status != models.StatusDown {
479			return nil
480		}
481		s.mu.Lock()
482		s.retries++
483		s.mu.Unlock()
484		return withRetry(3, func() error {
485			return s.notifier.Send("ops", "device "+id+" is still down")
486		})
487	}
488	
489	// Health reports whether the service can reach its repository and whether
490	// at least one cached device is ready.
491	func (s *DeviceService) Health(ctx context.Context) error {
492		if s.repo == nil {
493			return errors.New("device service: no repository")
494		}
495		if _, err := s.repo.List(ctx); err != nil {
496			return fmt.Errorf("device service: unhealthy: %w", err)
497		}
498		s.mu.Lock()
499		cached := make([]models.Device, 0, len(s.cache))
500		for _, d := range s.cache {
501			cached = append(cached, d)
502		}
503		s.mu.Unlock()
504		if len(cached) == 0 {
505			return nil
506		}
507		ready := 0
508		for _, d := range cached {
509			if s.isReady(ctx, d.Tenant, d.ID) {
510				ready++
511			}
512		}
513		if ready == 0 {
514			return fmt.Errorf("device service: none of %d cached devices is ready", len(cached))
515		}
516		return nil
517	}
518	
519	// Stats returns the current statistics.
520	func (s *DeviceService) Stats() Stats {
521		s.mu.Lock()
522		defer s.mu.Unlock()
523		st := Stats{
524			Cached:  len(s.cache),
525			Hits:    s.hits,
526			Misses:  s.misses,
527			Retries: s.retries,
528			Uptime:  time.Since(s.started),
529		}
530		for _, d := range s.cache {
531			if st.Oldest == nil || d.LastSeen.Before(*st.Oldest) {
532				seen := d.LastSeen
533				st.Oldest = &seen
534			}
535		}
536		return st
537	}
538	
539	// Flush writes every cached device back to the repository and returns how
540	// many were written.
541	func (s *DeviceService) Flush(ctx context.Context) int {
542		s.mu.Lock()
543		defer s.mu.Unlock()
544		flushed := 0
545		for key, d := range s.cache {
546			if seen, ok := s.lastSeen[d.ID]; ok && seen.After(d.LastSeen) {
547				d.LastSeen = seen
548				s.cache[key] = d
549			}
550			_ = s.repo.Save(ctx, d) // best effort
551			flushed++
552		}
553		return flushed
554	}
555	
556	// Close releases the service.
557	func (s *DeviceService) Close() error {
558		s.mu.Lock()
559		defer s.mu.Unlock()
560		s.cache = map[string]models.Device{}
561		return nil
562	}
563	
564	// flushLoop forgets devices that have been silent for longer than the
565	// flap window so the last-seen table does not grow without bound.
566	func (s *DeviceService) flushLoop() {
567		for {
568			time.Sleep(50 * time.Millisecond)
569			cutoff := time.Now().Add(-4 * flapWindow())
570			for id, seen := range s.lastSeen {
571				if seen.Before(cutoff) {
572					delete(s.lastSeen, id)
573				}
574			}
575		}
576	}
577	
578	// flapWindow returns the configured flap window.
579	func flapWindow() time.Duration {
580		return time.Duration(env.Config.FlapWindowSec) * time.Second
581	}
582	
583	// cacheKey builds the key under which a device is cached.
584	//
585	// The key is the tenant followed by a slash followed by the device id. The
586	// slash was chosen over a colon because the very first version of the
587	// service stored devices in a directory per tenant, and the on-disk layout
588	// leaked into the cache key when the directory store was replaced by the
589	// JSON file. Tenants are not allowed to contain slashes, so the key is
590	// unambiguous; device ids are not allowed to contain slashes either, which
591	// is enforced upstream by the provisioning tool that hands out ids. Should
592	// either of those constraints ever be relaxed, the key would have to be
593	// escaped, but nothing in the fleet today requires that and the extra
594	// allocation was measured to be noticeable on the heartbeat path when the
595	// fleet was at its largest. The repository package builds an equivalent key
596	// on its own; the two must agree, which they do today because both use the
597	// same separator, but there is no shared constant, so a change in one place
598	// has to be mirrored in the other by hand. This was discussed once and it
599	// was decided that the coupling is acceptable for a key that has not changed
600	// since the service was written.
601	//
602	
603	func cacheKey(tenant, id string) string {
604		return tenant + "/" + id
605	}
606

