1	package services
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	
8		"example.com/go-mini/internal/models"
9	)
10	
11	// Formatter formats alerts for the audit log.
12	type Formatter interface {
13		Format(a models.Alert) string
14		ContentType() string
15	}
16	
17	type plainFormatter struct{}
18	
19	func (plainFormatter) Format(a models.Alert) string {
20		return a.Channel + " -> " + a.Recipient + ": " + a.Summary
21	}
22	
23	func (plainFormatter) ContentType() string {
24		return "text/plain"
25	}
26	
27	type jsonFormatter struct{}
28	
29	func (jsonFormatter) Format(a models.Alert) string {
30		b, _ := json.Marshal(a)
31		return string(b)
32	}
33	
34	func (jsonFormatter) ContentType() string {
35		return "application/json"
36	}
37	
38	func newFormatter(kind string) Formatter {
39		if kind == "json" {
40			return jsonFormatter{}
41		}
42		return plainFormatter{}
43	}
44	
45	// AlertService is a service for alerts.
46	type AlertService struct {
47		notifier  *Notifier
48		audit     *AuditLog
49		formatter Formatter
50		raised    int
51		received  int
52		lastAt    time.Time
53	}
54	
55	// NewAlertService creates a new AlertService.
56	func NewAlertService(notifier *Notifier, audit *AuditLog, format string) *AlertService {
57		return &AlertService{
58			notifier:  notifier,
59			audit:     audit,
60			formatter: newFormatter(format),
61		}
62	}
63	
64	// Raise raises the alert that matches the device's status.
65	func (s *AlertService) Raise(d models.Device) error {
66		s.received++
67		s.lastAt = time.Now()
68		var a models.Alert
69	
70		switch d.Status {
71		case models.StatusReady:
72			return nil
73		case models.StatusDegraded:
74			a = models.Alert{Channel: models.ChannelSlack, Recipient: "#fleet", Summary: "device " + d.ID + " is degraded"}
75		case models.StatusDown:
76			a = models.Alert{Channel: models.ChannelPagerDuty, Recipient: "fleet-oncall", Summary: "device " + d.ID + " is down"}
77		default:
78			return fmt.Errorf("no alert for status %q", d.Status)
