package services

import (
	"errors"
	"fmt"
	"strings"

	"example.com/go-mini/internal/models"
)

// ParsedHeartbeat is the structured result of parsing a heartbeat line.
type ParsedHeartbeat struct {
	ID      string
	Status  string
	Version string
	Tags    []string
}

// ParseHeartbeatLine parses a heartbeat line of the form
// id|status|version|tag,tag. When lenient is true, a status outside the
// known set is accepted as StatusDegraded instead of failing.
func ParseHeartbeatLine(raw string, lenient bool) (ParsedHeartbeat, error) {
	parts := strings.Split(raw, "|")
	if len(parts) < 3 {
		return ParsedHeartbeat{}, errors.New("bad heartbeat")
	}
	id := strings.TrimSpace(parts[0])
	if id == "" || len(id) > 64 {
		return ParsedHeartbeat{}, errors.New("bad id")
	}
	status := strings.ToUpper(strings.TrimSpace(parts[1]))
	if !models.IsValidStatus(status) {
		if !lenient {
			return ParsedHeartbeat{}, fmt.Errorf("unknown status %q", status)
		}
		status = models.StatusDegraded
	}
	version := strings.TrimSpace(parts[2])
	var tags []string
	if len(parts) > 3 {
		tags = normalizeTags(strings.Split(parts[3], ","))
	}
	return ParsedHeartbeat{ID: id, Status: status, Version: version, Tags: tags}, nil
}

// normalizeTags trims, dedupes and drops region tags with unknown codes.
func normalizeTags(in []string) []string {
	var tags []string
	for _, raw := range in {
		t := strings.TrimSpace(raw)
		if t == "" || containsTag(tags, t) || !validTag(t) {
			continue
		}
		tags = append(tags, t)
	}
	return tags
}

// containsTag reports whether tags already contains t.
func containsTag(tags []string, t string) bool {
	for _, e := range tags {
		if e == t {
			return true
		}
	}
	return false
}

// validTag reports whether t is acceptable: any non-region tag, or a region
// tag whose code is eu, us, or ap.
func validTag(t string) bool {
	code, ok := strings.CutPrefix(t, "region:")
	if !ok {
		return true
	}
	return code == "eu" || code == "us" || code == "ap"
}

