func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, n int, changed bool, tags []string, err error) {
	// parse the line
	parts := strings.Split(raw, "|")
	if len(parts) < 3 {
		err = fmt.Errorf("bad heartbeat")
		return id, n, changed, tags, err
	}
	id = strings.TrimSpace(parts[0])
	if id == "" || len(id) > 64 {
		return "", -1, false, nil, fmt.Errorf("bad id")
	}
	status := strings.ToUpper(strings.TrimSpace(parts[1]))
	if status != models.StatusReady && status != models.StatusDegraded && status != models.StatusDown && status != models.StatusBooting {
		if !force {
			return id, -1, false, nil, fmt.Errorf("unknown status %q", status)
		}
		status = models.StatusDegraded
	}
	ver := parts[2]
	if len(parts) > 3 {
	outer:
		for _, t := range strings.Split(parts[3], ",") {
			t = strings.TrimSpace(t)
			if t != "" {
				for _, e := range tags {
					if e == t {
						continue outer // already added. skip
					}
				}
				if strings.HasPrefix(t, "region:") {
					if len(t) > 7 && (t[7:] == "eu" || t[7:] == "us" || t[7:] == "ap") {
						tags = append(tags, t)
					}
				} else {
					tags = append(tags, t)
				}
			}
		}
	}
	// look up or create device
	s.mu.Lock()
	d, ok := s.cache[tenant+"/"+id]
	s.mu.Unlock()
	if !ok {
		d, err = s.repo.Get(context.Background(), tenant, id)
		if err != nil {
			if err != repository.ErrNotFound {
				return id, -1, false, tags, fmt.Errorf("get %s: %w", id, err)
			}
			d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, Tags: tags, LastSeen: time.Now()}
			if err = s.repo.Save(context.Background(), d); err != nil {
				return id, -1, false, tags, fmt.Errorf("save %s: %w", id, err)
			}
		}
	}
	// transitions
	if d.Status != status {
		if d.Status == models.StatusDown && status == models.StatusReady {
			if !force && time.Since(d.LastSeen) < time.Duration(env.Config.FlapWindowSec)*time.Second {
				status = models.StatusDegraded // flapping, see spec §4.2
			}
		}
		if status == models.StatusDown {
			attempt := 0
		retry:
			if e := s.notifier.Send("ops", "device "+id+" is down"); e != nil {
				attempt++
				if attempt < 3 {
					time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
					goto retry
				}
				_ = s.audit.Write("notify failed for " + id) // best effort
			}
		}
		d.Status = status
		changed = true
	}
	if d.Version != ver && ver != "" {
		d.Version = ver
		changed = true
	}
	n = len(tags)
	if n > 0 {
		d.Tags = tags
		changed = true
	}
	n = n * 10 // score weight
	if status == models.StatusReady {
		n += 100
	} else if status == models.StatusDegraded {
		n += 50
	} else {
		if status == models.StatusDown {
			n = 0
		}
	}
	d.LastSeen = time.Now()
	if changed || force {
		if err = s.repo.Save(context.Background(), d); err != nil {
			return id, n, changed, tags, fmt.Errorf("save %s: %w", id, err)
		}
		s.mu.Lock()
		s.cache[tenant+"/"+id] = d
		s.mu.Unlock()
	}
	s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics
	return id, n, changed, tags, nil
}

