func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, n int, changed bool, tags []string, err error) {
	parsed, err := ParseHeartbeatLine(raw, force)
	if err != nil {
		return "", 0, false, nil, err
	}

	d, err := s.deviceForHeartbeat(tenant, parsed.ID, parsed.Tags)
	if err != nil {
		return parsed.ID, 0, false, parsed.Tags, err
	}

	status := s.resolveStatus(d, parsed.Status, force)
	changed = s.applyHeartbeat(&d, status, parsed)
	n = scoreHeartbeat(status, len(parsed.Tags))
	d.LastSeen = time.Now()

	if changed || force {
		if err := s.repo.Save(context.Background(), d); err != nil {
			return parsed.ID, n, changed, parsed.Tags, fmt.Errorf("save %s: %w", parsed.ID, err)
		}
		s.mu.Lock()
		s.cache[tenant+"/"+parsed.ID] = d
		s.mu.Unlock()
	}
	s.lastSeen[parsed.ID] = d.LastSeen // bounds-checked: map access never panics
	return parsed.ID, n, changed, parsed.Tags, nil
}

// deviceForHeartbeat returns the cached device for tenant/id, fetching it
// from the repository or creating a booting placeholder when it is not
// cached.
func (s *DeviceService) deviceForHeartbeat(tenant, id string, tags []string) (models.Device, error) {
	s.mu.Lock()
	d, ok := s.cache[tenant+"/"+id]
	s.mu.Unlock()
	if ok {
		return d, nil
	}
	d, err := s.repo.Get(context.Background(), tenant, id)
	if err == nil {
		return d, nil
	}
	if err != repository.ErrNotFound {
		return models.Device{}, fmt.Errorf("get %s: %w", id, err)
	}
	d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, Tags: tags, LastSeen: time.Now()}
	if err := s.repo.Save(context.Background(), d); err != nil {
		return models.Device{}, fmt.Errorf("save %s: %w", id, err)
	}
	return d, nil
}

// resolveStatus applies the flap-window rule: a device that goes DOWN
// straight to READY inside the flap window is reported as DEGRADED instead,
// so a device that reboots in a loop does not page anyone on every cycle
// (spec §4.2).
func (s *DeviceService) resolveStatus(d models.Device, status string, force bool) string {
	if d.Status == models.StatusDown && status == models.StatusReady &&
		!force && time.Since(d.LastSeen) < s.flapWindow {
		return models.StatusDegraded
	}
	return status
}

// applyHeartbeat mutates d to match the parsed heartbeat and reports whether
// anything changed. A transition into DOWN triggers a best-effort page.
func (s *DeviceService) applyHeartbeat(d *models.Device, status string, parsed ParsedHeartbeat) bool {
	changed := false
	if d.Status != status {
		if status == models.StatusDown {
			s.notifyDown(d.ID)
		}
		d.Status = status
		changed = true
	}
	if d.Version != parsed.Version && parsed.Version != "" {
		d.Version = parsed.Version
		changed = true
	}
	if len(parsed.Tags) > 0 {
		d.Tags = parsed.Tags
		changed = true
	}
	return changed
}

// notifyDown pages ops that id is down, retrying twice more on failure
// before giving up and recording a best-effort audit entry.
func (s *DeviceService) notifyDown(id string) {
	const maxAttempts = 3
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if err := s.notifier.Send("ops", "device "+id+" is down"); err == nil {
			return
		}
		if attempt < maxAttempts-1 {
			time.Sleep(time.Duration(attempt+1) * 200 * time.Millisecond)
		}
	}
	_ = s.audit.Write("notify failed for " + id) // best effort
}

// scoreHeartbeat computes the health score: status weight plus 10 per tag,
// except a device that is down always scores zero.
func scoreHeartbeat(status string, tagCount int) int {
	if status == models.StatusDown {
		return 0
	}
	n := tagCount * 10
	switch status {
	case models.StatusReady:
		n += 100
	case models.StatusDegraded:
		n += 50
	}
	return n
}

