	done := make(chan string, len(ids))
	jobs := make(chan pool.Job)
	pool.Start(jobs)

	for _, id := range ids {
		jobs <- pool.Job{ID: id, Run: func() { done <- id }}
	}
	close(jobs)

	seen := map[string]bool{}
	for range ids {
		seen[<-done] = true
	}
	for _, id := range ids {
