// Package jobs schedules background jobs onto the worker pool.
package jobs

import (
	"context"
	"fmt"
	"log"
	"slices"
	"sync"
	"time"

	"example.com/go-mini/internal/models"
	"example.com/go-mini/internal/pkg/deviceid"
	"example.com/go-mini/internal/pool"
	"example.com/go-mini/internal/repository"
)

// defaultRegion is used for a sync job that does not specify one.
const defaultRegion = "eu"

// Scheduler is the scheduler.
type Scheduler struct {
	batchSize  int
	numWorkers int
	store      *repository.MemStore
	queue      chan pool.Job
	mu         sync.Mutex
	pending    []models.Job
	wg         sync.WaitGroup
	completed  int
	failed     int
}

// NewScheduler creates a new Scheduler that dispatches onto numWorkers
// workers and buffers up to batchSize pending jobs per run.
func NewScheduler(batchSize, numWorkers int) *Scheduler {
	return &Scheduler{
		batchSize:  batchSize,
		numWorkers: numWorkers,
		store:      repository.NewMemStore(),
	}
}

// Store returns the scheduler's device store, for sync jobs to read and
// write and for tests to seed.
func (s *Scheduler) Store() *repository.MemStore {
	return s.store
}

// Enqueue adds a job to the pending list.
func (s *Scheduler) Enqueue(job models.Job) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.pending = append(s.pending, job)
}

// Run runs the scheduler.
func (s *Scheduler) Run(ctx context.Context) {
	ch := make(chan pool.Job, s.batchSize)
	pool.Start(ch, s.numWorkers)
	s.queue = ch
	defer close(ch)
	for _, job := range s.drain() {
		if ctx.Err() != nil {
			return
		}
		log.Printf("jobs: dispatch %s (%s)", truncate(job.ID, 8), job.Kind)
		s.wg.Add(1)
		ch <- pool.Job{ID: job.ID, Run: func() {
			defer s.wg.Done()
			s.record(s.dispatch(job))
		}}
	}
}

// Wait blocks until every dispatched job has finished.
func (s *Scheduler) Wait() {
	s.wg.Wait()
}

// Completed returns the number of jobs that finished without error.
func (s *Scheduler) Completed() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.completed
}

// Failed returns the number of jobs that returned an error.
func (s *Scheduler) Failed() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.failed
}

func (s *Scheduler) drain() []models.Job {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := s.pending
	s.pending = nil
	return out
}

func (s *Scheduler) record(err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err != nil {
		log.Printf("jobs: %v", err)
		s.failed++
		return
	}
	s.completed++
}

func (s *Scheduler) dispatch(job models.Job) error {
	switch job.Kind {
	case models.JobKindSnapshot:
		return runSnapshot(job)
	case models.JobKindSync:
		return Sync(context.Background(), s.store, job)
	default:
		return fmt.Errorf("jobs: unknown kind %q for job %s", job.Kind, job.ID)
	}
}

// truncate returns at most the first n bytes of s, for compact log lines.
func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

// Sync refreshes the device a sync job points at and stamps its region tag.
func Sync(ctx context.Context, repo repository.DeviceRepository, job models.Job) error {
	id, err := deviceid.Parse(job.DeviceID)
	if err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	d, err := repo.Get(ctx, job.Tenant, id.String())
	if err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	region := defaultRegion
	if r, ok := job.Settings["region"].(string); ok && r != "" {
		region = r
	}
	tag := "region:" + region
	if !slices.Contains(d.Tags, tag) {
		d.Tags = append(d.Tags, tag)
	}
	d.LastSeen = time.Now()
	if err := repo.Save(ctx, d); err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	return nil
}

