package services

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"
	"time"

	"example.com/go-mini/internal/models"
	"example.com/go-mini/internal/repository"
)

func TestNormalizeTags(t *testing.T) {
	got := normalizeTags([]string{" a ", "b", "a", "", "region:eu", "region:xx", "region:"})
	want := []string{"a", "b", "region:eu"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("normalizeTags() = %v, want %v", got, want)
	}
}

func TestParseHeartbeatLine(t *testing.T) {
	tests := []struct {
		name   string
		raw    string
		wantID string
	}{
		{name: "ready with tags", raw: "dev-1|ready|1.2.3|a,b", wantID: "dev-1"},
		{name: "lowercase status", raw: "dev-2|degraded|1.0", wantID: "dev-2"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			parsed, err := ParseHeartbeatLine(tt.raw, false)
			if err != nil {
				t.Fatalf("ParseHeartbeatLine(%q) unexpected error: %v", tt.raw, err)
			}
			if parsed.ID != tt.wantID {
				t.Errorf("id = %q, want %q", parsed.ID, tt.wantID)
			}
		})
	}
}

func TestParseHeartbeatLine_Errors(t *testing.T) {
	tests := []struct {
		name string
		raw  string
	}{
		{name: "too few fields", raw: "dev-3|ready"},
		{name: "empty id", raw: " |ready|1.0"},
		{name: "unknown status", raw: "dev-4|SLEEPY|1.0"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := ParseHeartbeatLine(tt.raw, false); err == nil {
				t.Fatalf("ParseHeartbeatLine(%q) expected an error", tt.raw)
			}
		})
	}
}

func TestParseHeartbeatLineTags(t *testing.T) {
	parsed, err := ParseHeartbeatLine("dev-1|ready|1.2.3|a, b ,a,region:eu,region:zz", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if parsed.Status != models.StatusReady || parsed.Version != "1.2.3" {
		t.Errorf("status, version = %q, %q", parsed.Status, parsed.Version)
	}
	if want := []string{"a", "b", "region:eu"}; !reflect.DeepEqual(parsed.Tags, want) {
		t.Errorf("tags = %v, want %v", parsed.Tags, want)
	}
}

func TestCacheExpiresEntries(t *testing.T) {
	c := NewCache(50 * time.Millisecond)
	c.Put(models.Device{ID: "d1", Tenant: "acme", Status: models.StatusReady})
	if _, ok := c.Get("acme/d1"); !ok {
		t.Fatal("expected a fresh entry to be cached")
	}
	time.Sleep(100 * time.Millisecond)
	if _, ok := c.Get("acme/d1"); ok {
		t.Fatal("expected the entry to expire")
	}
	if c.Len() != 0 {
		t.Errorf("Len() = %d, want 0", c.Len())
	}
}

func TestNotifierSend(t *testing.T) {
	var got webhookPayload
	var contentType string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		contentType = r.Header.Get("Content-Type")
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read body: %v", err)
		}
		if err := json.Unmarshal(body, &got); err != nil {
			t.Errorf("decode body: %v", err)
		}
		w.WriteHeader(http.StatusAccepted)
	}))
	defer srv.Close()

	if err := NewNotifier(srv.URL).Send("ops", "device d1 is down"); err != nil {
		t.Fatalf("Send: %v", err)
	}
	if !strings.EqualFold(contentType, "application/json") {
		t.Errorf("Content-Type = %q", contentType)
	}
	if got.Channel != "ops" || got.Message != "device d1 is down" || got.SentAt == "" {
		t.Errorf("payload = %+v", got)
	}
}

func TestNotifierSendServerError(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
	}))
	defer srv.Close()
	if err := NewNotifier(srv.URL).Send("ops", "x"); err == nil {
		t.Fatal("expected an error for a 500 response")
	}
}

