	if err := repo.Save(ctx, models.Device{ID: "d2", Tenant: "acme", Status: models.StatusReady, Tags: []string{"region:us"}}); err != nil {
		t.Fatal(err)
	}
	svc := NewSyncService(repo, NewNotifier(""), "eu", 10, 0, true)
	n, err := svc.Run(ctx)
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if n != 1 {
		t.Errorf("synced = %d, want 1", n)
	}
	if _, ok := svc.LastRun(); !ok {
		t.Error("expected LastRun to be set")
	}
