// Stats returns the current statistics.
func (s *DeviceService) Stats() Stats {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := Stats{
		Cached:  len(s.cache),
		Hits:    s.hits,
		Misses:  s.misses,
		Retries: s.retries,
		Uptime:  time.Since(s.started),
	}
